import { useShellStore } from '@/app/store/shellStore'
import type { AccentPreset } from '@/app/store/shellStore'

export function ProfileAppearancePage() {
  const { themeMode, setThemeMode, accentPreset, setAccentPreset } = useShellStore()

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-2xl mx-auto">
        <div className="bg-surface rounded-xl border border-border p-6">
          <h3 className="font-medium mb-4">Theme mode</h3>
          <div className="flex gap-2 mb-6">
            {(['light', 'dark', 'system'] as const).map((mode) => (
              <button key={mode} onClick={() => setThemeMode(mode)}
                className={`px-3 py-1.5 rounded-lg text-sm border capitalize ${themeMode === mode ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground'}`}>
                {mode}
              </button>
            ))}
          </div>
          <h3 className="font-medium mb-4">Accent preset</h3>
          <div className="flex gap-2">
            {(['green', 'blue', 'purple', 'orange', 'rose'] as AccentPreset[]).map((preset) => (
              <button key={preset} onClick={() => setAccentPreset(preset)}
                className={`px-3 py-1.5 rounded-lg text-sm border capitalize ${accentPreset === preset ? 'border-accent bg-accent/10 text-accent' : 'border-border text-muted-foreground'}`}>
                {preset}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}
